import copy

def _find_player(frame):
    cells = [(r, c) for r in range(63) for c in range(64) if frame[r][c] in (0, 14)]
    if not cells:
        return None
    return min(r for r, _ in cells), min(c for _, c in cells)

def predict(history, action):
    last = history[-1]
    frame = copy.deepcopy(last["frame"])
    g = frame[0]
    a = action.get("action", 5)

    # once the game is over nothing changes any more
    if last["state"] == "GAME_OVER":
        return {
            "frame": frame,
            "state": last["state"],
            "levels_completed": last["levels_completed"],
            "available_actions": list(last["available_actions"]),
        }

    pos = _find_player(g)
    if pos is not None and a in (1, 2, 3, 4):
        r0, c0 = pos
        # erase old player (row 63 is the status bar, never touched)
        for r in range(r0, min(r0 + 4, 63)):
            for c in range(c0, c0 + 4):
                g[r][c] = 1
        dr, dc = {1: (-4, 0), 2: (4, 0), 3: (0, -4), 4: (0, 4)}[a]
        nr, nc = r0 + dr, c0 + dc
        ok = 0 <= nr and nr + 3 <= 63 and 0 <= nc and nc + 3 <= 63
        if ok:
            for r in range(nr, min(nr + 4, 63)):
                for c in range(nc, nc + 4):
                    if g[r][c] != 1:
                        ok = False
        if ok:
            r0, c0 = nr, nc
        # draw player with facing edge (value 0)
        for r in range(r0, min(r0 + 4, 63)):
            for c in range(c0, c0 + 4):
                g[r][c] = 14
        if a == 1:
            if r0 <= 62:
                for c in range(c0, c0 + 4):
                    g[r0][c] = 0
        elif a == 2:
            if r0 + 3 <= 62:
                for c in range(c0, c0 + 4):
                    g[r0 + 3][c] = 0
        elif a == 3:
            for r in range(r0, min(r0 + 4, 63)):
                g[r][c0] = 0
        else:
            for r in range(r0, min(r0 + 4, 63)):
                g[r][c0 + 3] = 0

    # bottom bar: every action (move, blocked move or wait) counts as one
    # step out of a budget of 200; depleted cells = round(64 * used / 200),
    # filled from the right.
    used = (len(history) - 1) + 1
    n = (16 * used + 25) // 50  # == round(64*used/200), no exact ties
    n = max(0, min(64, n))
    for c in range(64):
        g[63][c] = 4 if c >= 64 - n else 7

    state = last["state"]
    if used >= 200:
        state = "GAME_OVER"

    return {
        "frame": frame,
        "state": state,
        "levels_completed": last["levels_completed"],
        "available_actions": list(last["available_actions"]),
    }
